const reviewFieldLabels={document_no:'Document number',party_name:'Customer / supplier',location:'Business location',occurred_at:'Transaction date and time',total_amount:'Total amount',paid_amount:'Amount paid',due_amount:'Amount outstanding',return_due_amount:'Return balance',source_status:'Payment / document status',line_no:'Line',sku:'SKU',description:'Item / description',entered_quantity:'Quantity',entered_uom:'Unit of measure',unit_price:'Unit price',subtotal:'Line total',relation_status:'Item-data status'};
