const reviewStatusLabels={in_review:'Review in progress',verified:'Verified',correction_required:'Correction required',corrected:'Correction saved — verification required',rejected:'Rejected',promoted:'Permanent ERP record'};
const technicalReviewFields=new Set(['migration_status','source_kind','evidence']);
const editableReviewFields=new Set(['party_name','location','occurred_at','total_amount','paid_amount','due_amount','return_due_amount','source_status']);
const amountReviewFields=new Set(['total_amount','paid_amount','due_amount','return_due_amount','unit_price','subtotal']);
function reviewValue(key,value){if(value===null||value===undefined||value==='')return 'Not available';if(amountReviewFields.has(key))return money(value);if(key==='occurred_at')return date(value);return String(value).replaceAll('_',' ')}
function renderReviewEvidence(payload){const fields=Object.entries(payload||{}).filter(([key])=>key!=='lines'&&!technicalReviewFields.has(key));const lines=Array.isArray(payload?.lines)?payload.lines:[];return `<div class="review-evidence-grid">${fields.map(([key,value])=>`<div><small>${esc(reviewFieldLabels[key]||key.replaceAll('_',' '))}</small><strong>${esc(reviewValue(key,value))}</strong></div>`).join('')}</div>${lines.length?`<h4>Items in this document</h4><div class="table-wrap"><table class="review-lines"><thead><tr><th>Line</th><th>Item / description</th><th>Quantity</th><th>Unit</th><th>Unit price</th><th>Line total</th><th>Item-data status</th></tr></thead><tbody>${lines.map((line,index)=>`<tr><td>${esc(line.line_no??index+1)}</td><td>${esc(line.description||line.product_name||line.sku||'Item description unavailable')}</td><td>${esc(line.entered_quantity??line.quantity??'—')}</td><td>${esc(line.entered_uom||line.uom||'—')}</td><td>${esc(line.unit_price==null?'—':money(line.unit_price))}</td><td>${esc(line.subtotal==null?'—':money(line.subtotal))}</td><td>${esc(reviewStatusLabels[line.relation_status]||String(line.relation_status||'Available').replaceAll('_',' '))}</td></tr>`).join('')}</tbody></table></div>`:'<p class="review-missing-lines"><b>Item details are not available in this capture.</b><span>The final BizModo capture must supply the invoice lines before this record can become permanent.</span></p>'}`}
function renderReviewCorrection(payload,editable){const fields=Object.entries(payload||{}).filter(([key])=>editableReviewFields.has(key));const lines=Array.isArray(payload?.lines)?payload.lines:[];return `<div class="review-correction-grid">${fields.map(([key,value])=>`<label>${esc(reviewFieldLabels[key])}<input data-review-field="${esc(key)}" ${amountReviewFields.has(key)?'type="number" step="0.01" min="0"':'type="text"'} value="${esc(value??'')}" ${editable?'':'disabled'}></label>`).join('')}</div>${lines.length?`<h4>Correct item values</h4><div class="table-wrap"><table class="review-lines review-line-inputs"><thead><tr><th>Line</th><th>SKU</th><th>Item / description</th><th>Quantity</th><th>Unit</th><th>Unit price</th><th>Line total</th></tr></thead><tbody>${lines.map((line,index)=>`<tr><td>${esc(line.line_no??index+1)}</td>${[['sku',null],['description',null],['entered_quantity','0.000001'],['entered_uom',null],['unit_price','0.0001'],['subtotal','0.01']].map(([key,step])=>`<td><input data-review-line="${index}" data-review-line-field="${key}" ${step?`type="number" min="0" step="${step}"`:'type="text"'} value="${esc(line[key]??'')}" ${editable?'':'disabled'}></td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}`}
function collectReviewCorrection(card,original){const corrected=JSON.parse(JSON.stringify(original||{}));card.querySelectorAll('[data-review-field]').forEach(input=>corrected[input.dataset.reviewField]=input.value);card.querySelectorAll('[data-review-line]').forEach(input=>{const index=Number(input.dataset.reviewLine);corrected.lines[index][input.dataset.reviewLineField]=input.value});return corrected}
async function reviewCenter(selectedKey=null,view='open'){
  const history=view==='verified',[d,suggestions,sourceVerification]=await Promise.all([api(`/data-reviews?status=${history?'verified':'open'}`),api('/data-review-suggestions'),api('/data-governance/source-verification')]),ctl=d.controls||{};
  const card=x=>{const editable=['in_review','correction_required','corrected'].includes(x.status),verify=['in_review','corrected'].includes(x.status),flag=['in_review','corrected','verified'].includes(x.status),evidence=x.source_payload||x.original_payload,source=x.corrected_payload||evidence,sourceLabel=x.source_enriched?'Complete item details recovered; review this revision again':x.source_status==='provisional_overlay'?'Newer BizModo header capture; item details were not available':'Captured migration record';return `<article class="panel review-card" data-key="${esc(x.review_key)}" data-revision="${x.revision}"><div class="panel-head"><div><h3>${esc(reviewTypeLabels[x.entity_type]||x.entity_type)} · ${esc(x.source_record_key)}</h3><span>${esc(sourceLabel)} · Review version ${x.revision}</span></div><span class="status ${esc(x.status)}">${esc(reviewStatusLabels[x.status]||x.status)}</span></div>${x.source_enriched?`<div class="review-enriched"><b>Item details restored safely.</b><span>${esc(x.source_enrichment_note||'Complete baseline evidence is now attached. The first-view evidence remains preserved in the audit history.')}</span></div>`:''}<div class="review-body"><section><h4>What BizModo showed</h4><p class="review-help">${x.source_enriched?'Complete preserved evidence is shown below. The earlier header-only evidence remains protected in the audit history.':'This original evidence is protected and cannot be overwritten.'}</p>${renderReviewEvidence(evidence)}</section><section><h4>${x.corrected_payload?'Saved corrected values':'Correct this record'}</h4><p class="review-help">Change only values that are wrong. Your correction is saved separately from the original.</p><label>Reason / reviewer note<textarea class="review-rationale" placeholder="For example: Amount paid should be AED 50 according to receipt 123">${esc(x.rationale||'')}</textarea></label>${renderReviewCorrection(source,editable)}<div class="review-actions">${verify?'<button data-action="verify" class="primary-small">Everything is correct</button>':''}${flag?'<button data-action="flag-incorrect">Something is wrong</button>':''}${editable?'<button data-action="correct">Save corrected values</button>':''}<button data-action="reject">Exclude this record</button><button data-action="promote" class="primary-small" ${x.promotion_available?'':'disabled'} title="${esc(x.promotion_blocker||'Available after approval')}">Make permanent in ERP</button></div><p class="review-blocker">${x.promotion_available?'All required checks have passed. This record is ready for controlled promotion.':`Cannot make permanent yet: ${esc(x.promotion_blocker||'Required checks are incomplete.')}`}</p></section></div></article>`};
  const selected=d.items.find(x=>x.review_key===selectedKey)||null;
  const queue=d.items.map(x=>`<button class="review-queue-item ${x.review_key===selectedKey?'selected':''}" data-review-key="${esc(x.review_key)}"><span><b>${esc(reviewTypeLabels[x.entity_type]||x.entity_type)}</b><strong>${esc(x.source_record_key)}</strong></span><span class="status ${esc(x.status)}">${esc(reviewStatusLabels[x.status]||x.status)}</span></button>`).join('');
  const priorityItems=suggestions.items.map(x=>`<article class="review-priority-item ${esc(x.severity)}"><div><span class="review-severity">${esc(x.severity)} priority</span><h4>${esc(reviewTypeLabels[x.entity_type]||x.entity_type)} · ${esc(x.document_no)}</h4><p>${esc(x.party_name||'Customer or supplier missing')} · ${esc(x.location||'Location missing')} · ${esc(money(x.total_amount))}</p><ul>${x.reasons.map(reason=>`<li>${esc(reason)}</li>`).join('')}</ul></div>${currentPermissions.has('migration.review')?`<button class="review-suggestion-start" data-entity="${esc(x.entity_type)}" data-key="${esc(x.document_no)}">Review this record</button>`:''}</article>`).join('');
  const priorityPanel=`<section class="panel review-priority"><div class="panel-head"><div><h3>Priority records to check</h3><span>${num(suggestions.total)} of ${num(suggestions.assessed)} remaining records need attention</span></div><span>Critical and high risk first</span></div>${priorityItems||'<div class="empty">No material transaction problems remain under the current automated checks.</div>'}<p class="footer-note">These are evidence-based suggestions, not automatic corrections. Confirm each record against the invoice, receipt or supplier document before changing anything.</p></section>`;
  content.innerHTML=hero('Review center','Verify captured evidence, record corrections separately, and control permanent ERP promotion','BizModo remains unchanged')+`<div class="metrics">${metric('Cloned records verified',num(sourceVerification.verified_records),'Checksum registry')}${metric('Review decisions',num(ctl.total),'Governed exceptions')}${metric('Open',num(ctl.open),'Needs a decision')}${metric('Priority problems',num(suggestions.severity_counts.critical+suggestions.severity_counts.high),'Automated checks')}</div>${priorityPanel}<div class="review-guide"><b>How it works</b><span>1. Source verification covers every immutable extracted row. 2. Exception reviews record separate decisions and corrections. 3. Promotion occurs only through a reconciled migration batch. 4. Posting stays disabled until cutover approval.</span><button type="button" id="review-history-toggle">${history?'Show reviews needing a decision':`View verified review history (${num(ctl.verified)})`}</button></div>${d.items.length?`<div class="review-workspace"><aside class="panel review-queue"><div class="panel-head"><div><h3>${history?'Verified history':'Needs review'}</h3><span>${num(d.total)} records</span></div></div>${queue}</aside><div class="review-list">${selected?card(selected):`<section class="panel empty review-selection-empty"><b>Select a ${history?'verified':'pending'} record</b><span>Only the record you select will open here.</span></section>`}</div></div>`:`<section class="panel empty">${history?'No verified review history is available.':'No reviews are waiting for a decision. All extracted clone records and Review Center decisions are verified.'}</section>`}`;
  document.querySelector('#review-history-toggle').onclick=()=>{location.hash=history?'reviews':'reviews?status=verified'};
  document.querySelectorAll('.review-suggestion-start').forEach(button=>button.onclick=async()=>{button.disabled=true;const response=await fetch('/api/v1/data-reviews',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({entity_type:button.dataset.entity,source_record_key:button.dataset.key})}),body=await response.json().catch(()=>({}));if(!response.ok){alert(body.detail||'Unable to start review');button.disabled=false;return}location.hash=`reviews?review=${encodeURIComponent(body.review_key)}`});
  document.querySelectorAll('.review-queue-item').forEach(button=>button.onclick=()=>{location.hash=`reviews?review=${encodeURIComponent(button.dataset.reviewKey)}`});
  document.querySelectorAll('.review-actions button[data-action]').forEach(button=>button.onclick=async()=>{const card=button.closest('.review-card'),action=button.dataset.action,rationale=card.querySelector('.review-rationale').value.trim()||null,record=d.items.find(item=>item.review_key===card.dataset.key);let corrected=null;if(action==='correct')corrected=collectReviewCorrection(card,record.corrected_payload||record.source_payload||record.original_payload);if(['flag-incorrect','reject'].includes(action)&&!rationale){alert('Please explain what is wrong before continuing.');return}button.disabled=true;try{await reviewAction(card.dataset.key,action,Number(card.dataset.revision),rationale,corrected);await reviewCenter(null,'open')}catch(e){alert(e.message);button.disabled=false}})
}
async function reports(){const d=await api('/reports'),o=d.delta_overlay||{},ds=o.deltas_from_prior_watermark||{};content.innerHTML=hero('Reports & controls','Migration quality and production-readiness evidence',d.snapshot)+`<div class="metrics">${metric('Source system',d.source_system)}${metric('Atomic capture',d.source_atomic?'Yes':'No')}${metric('Production ready',d.production_ready?'Yes':'No')}${metric('Posting',d.posting_enabled?'Enabled':'Disabled')}</div>${o.available?`<section class="panel"><div class="panel-head"><h3>Provisional delta overlay</h3><span>Hashes and row counts verified</span></div><div class="accounts">${Object.entries(ds).map(([k,v])=>`<div class="account-row"><div><b>${esc(k.replaceAll('_',' '))}</b><span>Movement from prior watermark</span></div><b>${v>=0?'+':''}${num(v)}</b><span>${num(o.counts[k])} current</span></div>`).join('')}</div><p class="footer-note">The newest transaction headers are visible, but incomplete child details remain blocked from posting.</p></section>`:''}<section class="panel"><div class="panel-head"><h3>Exception profile</h3><span>Controlled migration evidence</span></div><div class="accounts">${d.exceptions.map(x=>`<div class="account-row"><div><b>${esc(x.severity)} severity</b><span>${esc(x.queue_status)}</span></div><b>${num(x.count)}</b><span>records</span></div>`).join('')}</div></section>`}
async function route(){const raw=location.hash.slice(1)||'overview',[key,queryString='']=raw.split('?'),params=new URLSearchParams(queryString),active=routes[key]?key:'overview';title.textContent=routes[active];document.querySelectorAll('#nav a').forEach(a=>a.classList.toggle('active',a.dataset.route===active));content.innerHTML='<div class="loading">Loading cloned data…</div>';try{if(active==='overview')await overview();else if(active==='accounting')await accounting();else if(active==='reviews')await reviewCenter(params.get('review'),params.get('status')==='verified'?'verified':'open');else if(active==='reports')await reports();else if(active==='drafts')await draftWorkspace();else if(active==='inventory-operations')await inventoryOperations();else if(active==='goods-receipts')await goodsReceipts();else if(active==='sales-returns')await salesReturns();else if(active==='purchase-returns')await purchaseReturns();else if(active==='payments')await paymentsWorkspace();else if(active==='ageing')await ageingWorkspace();else await listing(active)}catch(e){content.innerHTML=`<div class="error"><b>Unable to load this workspace.</b><br>${esc(e.message)}</div>`}}
let csrf='',currentPermissions=new Set();
async function bootstrap(){const s=await api('/auth/session');if(!s.authenticated){location.replace('/login');return}csrf=s.csrf_token;currentPermissions=new Set(s.principal.permissions||[]);document.querySelector('#signed-in-user').textContent=s.principal.login_name;document.querySelector('#logout').onclick=async()=>{const r=await fetch('/api/v1/auth/logout',{method:'POST',headers:{'X-CSRF-Token':csrf}});if(r.ok)location.replace('/login')};await route()}
addEventListener('hashchange',route);bootstrap().catch(e=>{content.innerHTML=`<div class="error"><b>Unable to verify your session.</b><br>${esc(e.message)}</div>`});
